import{_ as o,o as l,c as a,a2 as t}from"./chunks/framework.DSoq407f.js";const p=JSON.parse('{"title":"发布与上架","description":"","frontmatter":{},"headers":[],"relativePath":"plugin-dev/publish.md","filePath":"plugin-dev/publish.md","lastUpdated":1782304957000}'),d={name:"plugin-dev/publish.md"};function i(c,e,r,s,n,h){return l(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="发布与上架" tabindex="-1">发布与上架 <a class="header-anchor" href="#发布与上架" aria-label="Permalink to &quot;发布与上架&quot;">​</a></h1><blockquote><p><strong>你会学到</strong>：怎么把写好的插件上传到平台、定价、上架到市场、赚取分成并提现。</p></blockquote><h2 id="开发者中心" tabindex="-1">开发者中心 <a class="header-anchor" href="#开发者中心" aria-label="Permalink to &quot;开发者中心&quot;">​</a></h2><p>V3 内置<strong>开发者中心</strong>。注册成为开发者后，你可以：</p><ul><li>上传和管理插件</li><li>管理插件版本</li><li>设置价格和上架状态</li><li>查看销量和收益</li><li>申请提现</li></ul><h2 id="上传插件" tabindex="-1">上传插件 <a class="header-anchor" href="#上传插件" aria-label="Permalink to &quot;上传插件&quot;">​</a></h2><ol><li>按插件目录结构打包好（至少 <code>meta.yaml</code> + <code>main.py</code>）。</li><li>在开发者中心点「上传插件」，提交 zip 包。</li><li>平台校验 <code>meta.yaml</code> 和入口文件，通过后插件进入「未上架」状态。</li></ol><div class="tip custom-block"><p class="custom-block-title">code 要稳定</p><p>上传时 <code>meta.yaml</code> 的 <code>code</code> 决定插件身份。<strong>一旦确定不要改</strong>——后续更新都用同一个 <code>code</code>，递增 <code>version</code> 即可。改 <code>code</code> 会被当成全新插件，历史销量和绑定丢失。</p></div><h2 id="版本管理" tabindex="-1">版本管理 <a class="header-anchor" href="#版本管理" aria-label="Permalink to &quot;版本管理&quot;">​</a></h2><p>每次上传会创建一个新版本：</p><ul><li><code>meta.yaml</code> 的 <code>version</code> 必须递增（语义化版本，如 <code>1.0.0</code> → <code>1.0.1</code>）。</li><li>客户可保持在旧版本或升级到新版本。</li><li>建议在 <code>description</code> 或更新日志里写清楚每个版本改了什么。</li></ul><h2 id="定价与上架" tabindex="-1">定价与上架 <a class="header-anchor" href="#定价与上架" aria-label="Permalink to &quot;定价与上架&quot;">​</a></h2><p>新插件默认 <code>allow_purchase: false</code>（<strong>不上架</strong>）。确认没问题后再上架：</p><table tabindex="0"><thead><tr><th>设置</th><th>说明</th></tr></thead><tbody><tr><td>价格</td><td><code>0</code> = 免费；&gt;0 = 付费，客户购买后才能装</td></tr><tr><td>允许购买</td><td>开启后插件出现在市场，可被购买</td></tr><tr><td>分类</td><td><code>game</code> / <code>system</code> / <code>tool</code> / <code>fun</code> / <code>social</code> / <code>ai</code> / <code>other</code></td></tr><tr><td>隐藏</td><td>内部插件可设为隐藏，不在市场展示</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">默认不上架</p><p>为避免误传或有问题的插件直接进入市场，<strong>新上传的插件默认不上架</strong>。你需要主动开启「允许购买」。</p></div><h2 id="审核机制" tabindex="-1">审核机制 <a class="header-anchor" href="#审核机制" aria-label="Permalink to &quot;审核机制&quot;">​</a></h2><p>平台管理员会对上架的插件进行<strong>审核</strong>：</p><ul><li>审核内容通常包括：功能是否正常、是否有恶意行为、是否合规。</li><li>审核通过后插件才会在市场正式可见。</li><li>审核未通过会给出原因，修改后重新提交。</li></ul><h2 id="收益与分成" tabindex="-1">收益与分成 <a class="header-anchor" href="#收益与分成" aria-label="Permalink to &quot;收益与分成&quot;">​</a></h2><p>客户购买付费插件产生的收入，按<strong>平台与开发者的分成比例</strong>结算：</p><ul><li>每笔购买记录分成，开发者份额进入开发者余额。</li><li>你可以在开发者中心查看收益明细（哪个客户、买了哪个插件、分成多少）。</li><li>收益可累积，达到提现门槛后申请提现。</li></ul><h2 id="提现" tabindex="-1">提现 <a class="header-anchor" href="#提现" aria-label="Permalink to &quot;提现&quot;">​</a></h2><ul><li>开发者中心申请提现，将余额提现到你的收款账户。</li><li>平台审核提现申请后处理打款。</li><li>具体提现门槛、到账时间、分成比例由平台运营方配置。</li></ul><h2 id="上架检查清单" tabindex="-1">上架检查清单 <a class="header-anchor" href="#上架检查清单" aria-label="Permalink to &quot;上架检查清单&quot;">​</a></h2><p>发布前过一遍这个清单：</p><ul><li>[ ] <code>meta.yaml</code> 的 <code>code</code> 稳定、<code>version</code> 已递增</li><li>[ ] <code>events</code> 只订阅必要的事件类型</li><li>[ ] <code>setting.json</code> 的字段都有合理的 <code>default</code> 和 <code>label</code></li><li>[ ] 主流程用 <code>context.reply()</code> / <code>context.sender_id</code> 等统一接口（跨平台）</li><li>[ ] 平台特有功能做了降级处理</li><li>[ ] 没有硬编码的测试数据 / 密钥</li><li>[ ] 异常有 try/except，不会让插件整个崩掉</li><li>[ ] <code>description</code> 写清楚了功能和用法</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>想了解平台运营方怎么审核你的插件 → <a href="./../admin/marketplace">管理后台 · 插件市场审核</a></li><li>开发者相关运营说明 → <a href="./../admin/developers">管理后台 · 开发者管理</a></li></ul>',28)])])}const m=o(d,[["render",i]]);export{p as __pageData,m as default};
